a.del_flag='0'
  and a.activity_id=#{activityId}
  and a.hotel_id=#{hotelId}
  and a.order_id=#{orderId}
  and a.guest_name like concat('%',#{guestName},'%')
  and a.room_number like concat('%',#{roomNumber},'%')
  and a.assign_status=#{assignStatus}

order by a.assign_id desc

