update yc_hotel_assign
hotel_id=#{hotelId}, order_id=#{orderId}, room_id=#{roomId}, guest_name=#{guestName}, phone=#{phone}, room_number=#{roomNumber}, check_in_date=#{checkInDate}, check_out_date=#{checkOutDate}, assign_status=#{assignStatus}, update_by=#{updateBy}, remark=#{remark}, update_time=sysdate()
where assign_id=#{assignId}
